events=[]
class Box:
 @property
 def value(self): events.append('get'); return 1
 @value.setter
 def value(self,value): events.append(('set',value))
box=Box()
def receiver(): events.append('receiver'); return box
def rhs(): events.append('rhs'); return 2
receiver().value+=rhs()
print(events)

class Box:
 @property
 def value(self): return payload
payload=[1]
try: Box().value+=[2]
except AttributeError: print(payload)

events=[]
class Value:
 def __iadd__(self,other): events.append('iadd'); raise ValueError('bad')
class Box: pass
box=Box();original=Value();box.value=original
def rhs(): events.append('rhs'); return 2
try: box.value+=rhs()
except ValueError: print(events,box.value is original)

class Box: pass
def rhs(): raise AssertionError('rhs ran')
try: Box().missing+=rhs()
except AttributeError: print('missing')

events=[]
class D:
 def __init__(self,name): self.name=name
 def __get__(self,obj,owner): events.append(('get',self.name)); return 1
 def __set__(self,obj,value): events.append(('set',self.name,value))
class C: value=D('old')
obj=C()
def rhs(): C.value=D('new'); return 2
obj.value+=rhs()
print(events)

class Base:
 @property
 def value(self): return self.saved
 @value.setter
 def value(self,value): self.saved=value
class Child(Base): pass
box=Child();box.saved=1
box.value+=2
print(box.value)
